-- Insert the staged rows that the targets lack. A short staging table means that a
-- batch above failed (sqlcmd without -b goes on): then nothing is inserted.
DECLARE @npc_total int = (SELECT COUNT(*) FROM #u2_npcs);
DECLARE @mon_total int = (SELECT COUNT(*) FROM #u2_monsters);
DECLARE @npc_inserted int;
DECLARE @mon_inserted int;

IF @npc_total <> 82 OR @mon_total <> 60
BEGIN
    RAISERROR(N'staging tables have %d/%d rows, expected 82/60; nothing inserted', 16, 1, @npc_total, @mon_total);
    RETURN;
END

BEGIN TRANSACTION;

-- npc: record the ids that are about to be inserted, then insert them.
INSERT INTO dbo.$(NpcTarget)_U2_ADDED (sSid)
SELECT s.sSid
FROM #u2_npcs AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(NpcTarget) AS t WHERE t.sSid = s.sSid)
  AND NOT EXISTS (SELECT 1 FROM dbo.$(NpcTarget)_U2_ADDED AS a WHERE a.sSid = s.sSid);

INSERT INTO dbo.$(NpcTarget) (
    sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
    byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
    sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
    bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
    sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
    byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
)
SELECT
    sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
    byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
    sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
    bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
    sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
    byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
FROM #u2_npcs AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(NpcTarget) AS t WHERE t.sSid = s.sSid);

SET @npc_inserted = @@ROWCOUNT;

-- monster: record the ids that are about to be inserted, then insert them.
INSERT INTO dbo.$(MonTarget)_U2_ADDED (sSid)
SELECT s.sSid
FROM #u2_monsters AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(MonTarget) AS t WHERE t.sSid = s.sSid)
  AND NOT EXISTS (SELECT 1 FROM dbo.$(MonTarget)_U2_ADDED AS a WHERE a.sSid = s.sSid);

INSERT INTO dbo.$(MonTarget) (
    sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
    byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
    sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
    bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
    sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
    byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
)
SELECT
    sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
    byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
    sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
    bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
    sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
    byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
FROM #u2_monsters AS s
WHERE NOT EXISTS (SELECT 1 FROM dbo.$(MonTarget) AS t WHERE t.sSid = s.sSid);

SET @mon_inserted = @@ROWCOUNT;

COMMIT TRANSACTION;

PRINT 'npc inserted=' + CAST(@npc_inserted AS varchar(10))
    + ' already_present=' + CAST(@npc_total - @npc_inserted AS varchar(10));
PRINT 'monster inserted=' + CAST(@mon_inserted AS varchar(10))
    + ' already_present=' + CAST(@mon_total - @mon_inserted AS varchar(10));
GO

-- Verification: row counts, logged ids, and staged rows that are not in the
-- target with exactly these values (0 after a clean run).
DECLARE @npc_rows int = (SELECT COUNT(*) FROM dbo.$(NpcTarget));
DECLARE @npc_logged int = (SELECT COUNT(*) FROM dbo.$(NpcTarget)_U2_ADDED);
DECLARE @npc_differ int = (SELECT COUNT(*) FROM (
    SELECT
        sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
        byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
        sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
        bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
        sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
        byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
    FROM #u2_npcs
    EXCEPT
    SELECT
        sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
        byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
        sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
        bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
        sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
        byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
    FROM dbo.$(NpcTarget)) AS d);
PRINT 'npc target_rows=' + CAST(@npc_rows AS varchar(10))
    + ' logged=' + CAST(@npc_logged AS varchar(10))
    + ' staged_not_in_target=' + CAST(@npc_differ AS varchar(10));

DECLARE @monster_rows int = (SELECT COUNT(*) FROM dbo.$(MonTarget));
DECLARE @monster_logged int = (SELECT COUNT(*) FROM dbo.$(MonTarget)_U2_ADDED);
DECLARE @monster_differ int = (SELECT COUNT(*) FROM (
    SELECT
        sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
        byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
        sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
        bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
        sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
        byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
    FROM #u2_monsters
    EXCEPT
    SELECT
        sSid, strName, sPid, sSize, iWeapon1, iWeapon2, byGroup, byActType, byType,
        byFamily, byRank, byTitle, iSellingGroup, sLevel, iExp, iLoyalty, iHpPoint,
        sMpPoint, sAtk, sAc, sHitRate, sEvadeRate, sDamage, sAttackDelay, bySpeed1,
        bySpeed2, sStandtime, iMagic1, iMagic2, iMagic3, sFireR, sColdR, sLightningR,
        sMagicR, sDiseaseR, sPoisonR, sLightR, sBulk, byAttackRange, bySearchRange,
        byTracingRange, iMoney, sItem, byDirectAttack, byMagicAttack, byMoneyType
    FROM dbo.$(MonTarget)) AS d);
PRINT 'monster target_rows=' + CAST(@monster_rows AS varchar(10))
    + ' logged=' + CAST(@monster_logged AS varchar(10))
    + ' staged_not_in_target=' + CAST(@monster_differ AS varchar(10));

DROP TABLE #u2_npcs;
DROP TABLE #u2_monsters;
GO
